  /**
   * @typedef {Object} FluidInput
   * @property {string} name
   * @property {number} density_kg_per_m3
   *
   * @typedef {Object} DesignPointInput
   * @property {number} capacity_m3_per_h
   * @property {number} differential_head_m
   *
   * @typedef {Object} TestPointInput
   * @property {number} capacity_m3_per_h
   * @property {number} differential_head_m
   * @property {number} breaking_power_kw
   *
   * @typedef {Object} FitCurveResponse
   * @property {number[]} flow_rates_m3_per_h
   * @property {number[]} heads_m
   * @property {number[]} powers_kw
   * @property {number[]} efficiencies_pct
   * @property {number} r_squared
   * @property {string} status
   */

  export class PumpApiError extends Error {
    constructor(message, status, detail) {
      super(message);
      this.name = 'PumpApiError';
      this.status = status;
      this.detail = detail;
    }
  }

  /**
   * @param {{ fluid: FluidInput, design_point: DesignPointInput, test_points: TestPointInput[] }} payload
   * @param {{ baseUrl?: string, signal?: AbortSignal }} [opts]
   * @returns {Promise<FitCurveResponse>}
   */
  export async function fitCurve(payload, opts = {}) {
    const baseUrl = opts.baseUrl ?? '';
    const res = await fetch(`${baseUrl}/api/analysis/fit-curve`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(payload),
      signal: opts.signal,
    });
    if (!res.ok) {
      let detail;
      try { detail = await res.json(); } catch { detail = await res.text(); }
      throw new PumpApiError(`fit-curve failed (${res.status})`, res.status, detail);
    }
    return /** @type {FitCurveResponse} */ (await res.json());
  }

