  import React, { useState } from 'react';
  import { fitCurve, PumpApiError } from '../api/pumpClient.js';

  const DEFAULT_PAYLOAD = {
    fluid: { name: 'Water', density_kg_per_m3: 1000 },
    design_point: { capacity_m3_per_h: 100, differential_head_m: 50 },
    test_points: [
      { capacity_m3_per_h: 80, differential_head_m: 55, breaking_power_kw: 15 },
      { capacity_m3_per_h: 100, differential_head_m: 50, breaking_power_kw: 17 },
      { capacity_m3_per_h: 120, differential_head_m: 43, breaking_power_kw: 19 },
    ],
  };

  export default function MinimalFitDemo() {
    const [payload, setPayload] = useState(JSON.stringify(DEFAULT_PAYLOAD, null, 2));
    const [result, setResult] = useState(null);
    const [error, setError] = useState(null);
    const [loading, setLoading] = useState(false);

    async function handleSubmit(e) {
      e.preventDefault();
      setLoading(true); setError(null); setResult(null);
      try {
        const parsed = JSON.parse(payload);
        const data = await fitCurve(parsed);
        setResult(data);
      } catch (err) {
        setError(err instanceof PumpApiError ? `${err.message}: ${JSON.stringify(err.detail)}` : String(err));
      } finally {
        setLoading(false);
      }
    }

    return (
      <section style={{padding: 24, fontFamily: 'system-ui'}}>
        <h1>PumpLab — End-to-End Proof</h1>
        <form onSubmit={handleSubmit}>
          <textarea value={payload} onChange={(e) => setPayload(e.target.value)}
                    rows={18} cols={70} aria-label='request-json' />
          <div><button type='submit' disabled={loading}>{loading ? 'Fitting…' : 'Fit curve'}</button></div>
        </form>
        {error && <pre data-testid='error' style={{color: 'crimson'}}>{error}</pre>}
        {result && (
          <div data-testid='result'>
            <p>R² = {result.r_squared.toFixed(4)}</p>
            <p>Samples = {result.flow_rates_m3_per_h.length}</p>
          </div>
        )}
      </section>
    );
  }

